<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">PLATFORM CONFIGURATION</div><h1>Payment Gateways</h1><p>Credentials are stored encrypted and are never rendered into frontend JavaScript.</p></div></div><?php $__currentLoopData = $gateways; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $gateway): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="panel gateway-card"><div class="panel-head"><div><h3><?php echo e($gateway->name); ?></h3><p><?php echo e(strtoupper($gateway->slug)); ?></p></div><span class="badge <?php echo e($gateway->status?'success':'neutral'); ?>"><?php echo e($gateway->status?'Enabled':'Disabled'); ?></span></div><form method="POST" action="<?php echo e(route('settings.gateways.update',$gateway)); ?>"><?php echo csrf_field(); ?><div class="form-grid"><label>Environment<select name="environment"><option value="test" <?php if($gateway->environment==='test'): echo 'selected'; endif; ?>>Test</option><option value="staging" <?php if($gateway->environment==='staging'): echo 'selected'; endif; ?>>Staging</option><option value="production" <?php if($gateway->environment==='production'): echo 'selected'; endif; ?>>Production</option></select></label><label class="checkbox-line"><input type="checkbox" name="status" value="1" <?php if($gateway->status): echo 'checked'; endif; ?>> Enable gateway</label></div><div class="notice"><?php echo e($gateway->slug==='razorpay'?'Configure RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET and RAZORPAY_WEBHOOK_SECRET in .env.':'Configure PAYTM_MID, PAYTM_MERCHANT_KEY and Paytm environment values in .env.'); ?></div><div class="form-actions"><button class="btn primary">Save Settings</button></div></form></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>@endsection

